INSERT INTO fiscal_admin_unit VALUES ('admin:4900000:4', '서귀포시', 'ADMIN_CITY', 'lofin:laf:4900000', '4', '제주', '제주특별자치도 행정시. 제주본청 세출의 부서코드 앞자리 4. 2026-10-04 공개 snapshot 대조: 4005010 ''아름다운 서귀포시 사진 공모전''·''희망서귀포 제작'', 4005050 ''서귀포시정 안내책자'', 대정·성산 지명 사업이 모두 4로 시작한다. 작업지시서 P7의 서귀포시 통합돌봄과 부서코드 4005301과도 맞는다.', 'VERIFIED');
